// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 1 wei);
        vm.prank(address(0x1));
        bool ok;
        try c.addToBalance{value: 1 wei}() { ok = true; } catch { ok = false; }
        assertTrue(c.getBalance(address(0x1)) == 1 wei);
    }
}
